export const LEVELS = ['A1', 'A2', 'B1', 'B2', 'C1', 'C2'];

export const POS_LABEL = {
  n: 'noun', v: 'verb', adj: 'adjective', adv: 'adverb', prep: 'preposition', conj: 'conjunction',
  pron: 'pronoun', det: 'determiner', num: 'number', ex: 'exclamation', mod: 'modal verb', phr: 'phrase',
};

/** Collections shown in the library. */
export const COLLECTIONS = ['words', 'phrasal', 'phrases'];

let cache = null;

/**
 * Parsed library: [{ word, key, pos, level, academic, kind, topics }]
 * kind: 'word' | 'phrasal' | 'phrase'; topics: topic ids (see phrases.js).
 * Each item appears once (first occurrence wins; topic tags are merged).
 */
export function library() {
  if (cache) return cache;
  const byKey = new Map();
  cache = [];
  const push = (item) => {
    const old = byKey.get(item.key);
    if (old) { for (const tp of item.topics) if (!old.topics.includes(tp)) old.topics.push(tp); return; }
    byKey.set(item.key, item);
    cache.push(item);
  };
  const parse = (text, level, kind, topic) => {
    for (const tok of text.split(/\s+/)) {
      if (!tok) continue;
      const parts = tok.split(':');
      const word = parts[0].replace(/_/g, ' ');
      let pos = parts[1] || (kind === 'phrasal' ? 'phrasal verb' : 'phr');
      const academic = pos.endsWith('*');
      if (academic) pos = pos.slice(0, -1);
      const lvl = parts[2] || level;
      const k = kind === 'auto' ? (pos === 'v' && word.includes(' ') ? 'phrasal' : word.includes(' ') ? 'phrase' : 'word') : kind;
      push({ word, key: word.toLowerCase(), pos: POS_LABEL[pos] || pos, level: lvl, academic: academic || kind === 'phrase', kind: k, topics: topic ? [topic] : [] });
    }
  };
  for (const level of LEVELS) {
    if (RAW[level]) parse(RAW[level], level, 'word');
    if (EXTRA[level]) parse(EXTRA[level], level, 'word');
  }
  for (const [level, text] of Object.entries(PHRASAL)) parse(text, level, 'phrasal');
  for (const [level, text] of Object.entries(COLLOCATIONS)) parse(text, level, 'phrase');
  for (const [topic, text] of Object.entries(TOPICS)) parse(text, 'B1', 'auto', topic);
  return cache;
}

export const levelWords = (level) => library().filter((w) => w.level === level && w.kind === 'word');
